104  __aicore__ inline bool GetUnpackLocalTaskRange(
105      const UnpackTaskRange& assignedRange, const UnpackTaskSpan& span, UnpackTaskRange& localRange)
106  {
107      if (span.count == 0) {
108          return false;
109      }
110      const uint64_t spanEnd = span.start + span.count;
111      const uint64_t start = assignedRange.start > span.start ? assignedRange.start : span.start;
112      const uint64_t end = assignedRange.end < spanEnd ? assignedRange.end : spanEnd;
113      if (start >= end) {
114          return false;
115      }
116      localRange.start = start - span.start;
117      localRange.end = end - span.start;
118      return true;
119  }
