132          const uint64_t rightPadding = (paddedRowBytes - rowBytes) / sizeof(T);
133          if (tilingData.outerSize > 1 && rowBytes > 0 && rowBytes <= kUnpackRowBurstMaxBytes &&
134              rightPadding <= 255) {
135              uint64_t rowsPerTask = kUnpackRowBurstMaxBytes / paddedRowBytes;
136              rowsPerTask = rowsPerTask == 0 ? 1 : rowsPerTask;
137              rowsPerTask = rowsPerTask > tilingData.outerSize ? tilingData.outerSize : rowsPerTask;
138              plan.rowBurstRowsPerTask = rowsPerTask;
139              plan.rowBurstRowBlocks = CeilDivU64(tilingData.outerSize, plan.rowBurstRowsPerTask);
140              AppendUnpackTaskSpan(plan, plan.rowBurstCopyTasks, tilingData.num * plan.rowBurstRowBlocks);
141              return plan;
142          }
143          plan.chunksPerOutput = CeilDivU64(tilingData.innerSize, plan.copyTileSize);
144          AppendUnpackTaskSpan(plan, plan.copyChunkTasks, tilingData.num * tilingData.outerSize * plan.chunksPerOutput);
145          return plan;
