292  __aicore__ inline UnpackRowBurstTaskDesc GetUnpackRowBurstTask(
293      uint64_t task, const UnpackTilingData& tilingData, const UnpackSchedulePlan& plan)
294  {
295      const uint64_t outputIndex = plan.rowBurstRowBlocks == 0 ? 0 : task / plan.rowBurstRowBlocks;
296      const uint64_t rowBlock = plan.rowBurstRowBlocks == 0 ? 0 : task - outputIndex * plan.rowBurstRowBlocks;
297      const uint64_t rowStart = rowBlock * plan.rowBurstRowsPerTask;
298      const uint32_t rows = static_cast<uint32_t>(
299          MinU64(plan.rowBurstRowsPerTask, tilingData.outerSize - rowStart));
300      const uint32_t rowBytes = static_cast<uint32_t>(tilingData.innerSize * sizeof(T));
301      const uint32_t paddedRowBytes = AlignUp32(rowBytes);
302      const uint32_t rightPadding = (paddedRowBytes - rowBytes) / sizeof(T);
303      const uint32_t srcStrideBytes = static_cast<uint32_t>((tilingData.num - 1) * tilingData.innerSize * sizeof(T));
304  
305      return {
306          static_cast<uint32_t>(outputIndex),
307          (rowStart * tilingData.num + outputIndex) * tilingData.innerSize,
308          rowStart * tilingData.innerSize,
309          rows,
310          rowBytes,
311          paddedRowBytes,
312          rightPadding,
313          srcStrideBytes};

